import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../core/providers/app_providers.dart';import '../features/onboarding/presentation/onboarding_screen.dart';import '../features/home/presentation/home_screen.dart';import '../features/discover/presentation/discover_screen.dart';import '../features/pets/presentation/pets_screen.dart';import '../features/saved/presentation/saved_screen.dart';import '../features/settings/presentation/settings_screen.dart';
class AppShell extends ConsumerStatefulWidget{const AppShell({super.key});@override ConsumerState<AppShell> createState()=>_AppShellState();}
class _AppShellState extends ConsumerState<AppShell> with WidgetsBindingObserver{int selected=0;@override void initState(){super.initState();WidgetsBinding.instance.addObserver(this);}@override void didChangeAppLifecycleState(AppLifecycleState state){if(state==AppLifecycleState.resumed)ref.read(appControllerProvider).resyncNotifications();}@override void dispose(){WidgetsBinding.instance.removeObserver(this);super.dispose();}static const pages=[HomeScreen(),DiscoverScreen(),PetsScreen(),SavedScreen(),SettingsScreen()];@override Widget build(BuildContext context){final state=ref.watch(appControllerProvider);if(!state.isLoaded)return const Scaffold(body:Center(child:CircularProgressIndicator()));if(!state.onboardingComplete)return const OnboardingScreen();return Scaffold(body:SafeArea(child:IndexedStack(index:selected,children:pages)),bottomNavigationBar:NavigationBar(selectedIndex:selected,onDestinationSelected:(v)=>setState(()=>selected=v),destinations:const[NavigationDestination(icon:Icon(Icons.home_outlined),selectedIcon:Icon(Icons.home),label:'Home'),NavigationDestination(icon:Icon(Icons.explore_outlined),selectedIcon:Icon(Icons.explore),label:'Discover'),NavigationDestination(icon:Icon(Icons.pets_outlined),selectedIcon:Icon(Icons.pets),label:'My Pets'),NavigationDestination(icon:Icon(Icons.bookmark_border),selectedIcon:Icon(Icons.bookmark),label:'Saved'),NavigationDestination(icon:Icon(Icons.settings_outlined),selectedIcon:Icon(Icons.settings),label:'Settings')]));}}
